<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Catalog;final class WordPressPatientEducationCatalogRepository implements PatientEducationCatalogRepository{public function __construct(private object$db){}public function publishedForContext(string$organizationId,int$limit=50):array{$r=$this->db->prefix.'atlas_resources';$v=$this->db->prefix.'atlas_resource_versions';$c=$this->db->prefix.'atlas_citations';$s=$this->db->prefix.'atlas_sources';$limit=max(1,min(50,$limit));$rows=$this->db->get_results($this->db->prepare("SELECT r.id resource_id,r.scope,v.id version_id,v.title,v.summary,(SELECT source.publisher FROM `{$c}` citation INNER JOIN `{$s}` source ON source.id=citation.source_id WHERE citation.resource_version_id=v.id ORDER BY citation.display_order,citation.id LIMIT 1) source_publisher FROM `{$r}` r INNER JOIN `{$v}` v ON v.id=r.current_version_id WHERE r.resource_type='patient_education' AND v.review_status='published' AND (r.scope IN ('platform','public') OR (r.scope='organization' AND r.organization_id=%s)) ORDER BY CASE WHEN r.scope='organization' THEN 0 ELSE 1 END,v.title,r.id LIMIT %d",$organizationId,$limit),ARRAY_A);if(!is_array($rows)){return[];}return array_map(static fn(array$row):PatientEducationItem=>new PatientEducationItem((string)$row['resource_id'],(string)$row['version_id'],(string)$row['title'],(string)$row['summary'],(string)$row['scope'],$row['source_publisher']===null?null:(string)$row['source_publisher']),$rows);}}
